import json, urllib.request, urllib.error, time

token = open('/tmp/ivx_owner_token.txt').read().strip()
job_id = 'ivx-worker-d98f5510-71b8-40a5-939f-a57f82641e7e'

def poll_job():
    req = urllib.request.Request(
        f'https://api.ivxholding.com/api/ivx/senior-developer/worker/jobs/{job_id}',
        headers={'Authorization': f'Bearer {token}', 'Accept': 'application/json'}
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return json.loads(resp.read().decode())
    except urllib.error.HTTPError as e:
        return {'error': f'HTTP {e.code}', 'body': e.read().decode()[:300]}
    except Exception as e:
        return {'error': str(e)[:200]}

# Poll every 15 seconds for up to 5 minutes
for attempt in range(20):
    result = poll_job()
    if 'error' in result:
        print(f"  Attempt {attempt+1}: {result}")
    else:
        job = result.get('job', result)
        status = job.get('status', '?')
        stage = job.get('stage', '?')
        progress = job.get('progressPercent', 0)
        detail = job.get('stageDetail', '')[:100]
        ok = job.get('ok')
        finalStatus = job.get('finalStatus')
        commitSha = job.get('commitSha')
        print(f"  Attempt {attempt+1}: status={status} stage={stage} progress={progress}% ok={ok} finalStatus={finalStatus} commit={str(commitSha)[:12] if commitSha else 'N/A'} detail={detail}")

        if status in ('completed', 'failed', 'blocked') or finalStatus in ('COMPLETE', 'FAILED', 'BLOCKED'):
            print(f"\n=== JOB COMPLETED ===")
            print(json.dumps(job, indent=2)[:2000])
            break
    time.sleep(15)
else:
    print("Polling timed out after 5 minutes. Last status:")
    print(json.dumps(poll_job(), indent=2)[:1000])
PYEOF

